// Constructor functions and namespace functions, some provably the same as
// classes and direct functions, others observably different.
var ns = ns || {};
ns.util = ns.util || {};

ns.util.twice = function (x) {
  return 2 * x;
};
ns.util.isSelf = function () {
  return this === ns.util;
};

// Indistinguishable from a class.
ns.Point = function (x, y) {
  this.x = x;
  this.y = y;
};
ns.Point.prototype.norm = function () {
  return Math.sqrt(this.x * this.x + this.y * this.y);
};
ns.Point.prototype.moved = function (dx) {
  return new ns.Point(this.x + ns.util.twice(dx), this.y);
};

// Called without `new` as well.
ns.Box = function (v) {
  this.v = v;
};
ns.Box.prototype.get = function () {
  return this.v;
};

// Its prototype members are enumerable through instances.
ns.Bag = function () {
  this.a = 1;
};
ns.Bag.prototype.m = function () {
  return 2;
};

// Its name is read.
ns.Named = function () {
  this.n = 0;
};
ns.Named.prototype.n2 = function () {
  return this.n + 2;
};

ns.run = function () {
  var out = [];
  var p = new ns.Point(3, 4);
  out.push(p.norm(), p.moved(1).x, p instanceof ns.Point, Object.keys(p).join("|"));
  var holder = {};
  ns.Box.call(holder, 7);
  out.push(holder.v, new ns.Box(5).get());
  var keys = [];
  for (var k in new ns.Bag()) keys.push(k);
  out.push(keys.join("|"));
  out.push(JSON.stringify(ns.Named.name), new ns.Named().n2());
  out.push(ns.util.twice(21), ns.util.isSelf());
  return out.join(" ");
};

module.exports = { ns };
